contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, uint256 amount) public {
        uint256 fromBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBalBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 fromBalAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBalAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(reverted ? (fromBalAfter == fromBalBefore && toBalAfter == toBalBefore) : (fromBalAfter + amount == fromBalBefore && toBalAfter == toBalBefore + amount));
    }
}

